-- Single atomic statement: validates (md5 + importer dry run) then inserts. Deferred registry checks run at commit.
do $do$
declare
  v_text text := $pkg${"T":{"t0":{"primarySkillCode":"eng.writing.vocabulary-control","atomicSubskillCode":"eng.writing.vocabulary-control.precision","evidenceFocusCode":"eng.writing.vocabulary-control.precision.focus.core-demonstration","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Understands the defining features of a named shape well enough to identify it from a drawing or real-world object."},"t1":{"primarySkillCode":"eng.writing.vocabulary-control","atomicSubskillCode":"eng.writing.vocabulary-control.precision","evidenceFocusCode":"eng.writing.vocabulary-control.precision.focus.core-demonstration","assessmentProcessCode":"BH-AO1","cognitiveProcess":"remember","evidenceStatement":"Recalls the names of the parts of a solid (face, edge, vertex) from a marked diagram."},"t2":{"primarySkillCode":"eng.writing.vocabulary-control","atomicSubskillCode":"eng.writing.vocabulary-control.precision","evidenceFocusCode":"eng.writing.vocabulary-control.precision.focus.core-demonstration","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Applies shape vocabulary to name the solid that a flat net folds into."},"t3":{"primarySkillCode":"eng.use-of-english.lexical-patterns","atomicSubskillCode":"eng.use-of-english.lexical-patterns.semantic-relations","evidenceFocusCode":"eng.use-of-english.lexical-patterns.semantic-relations.focus.core-demonstration","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Distinguishes flat 2D shape words from solid 3D shape words and links each flat shape to its solid."}},"Q":[["01","Look at the picture. Which solid is this?",["cube","square","cuboid","square-based pyramid"],"cube","Six equal square faces make a cube. A cuboid has rectangular faces that are not all the same.","easy",60,["picture","cube","practice","easy"],["t0"],"esl-shape-cube.0fe4cf64b36b.svg","0fe4cf64b36bb50811437a14e1a461a90f5a6c6c43f412aaf3d66ddbbc613ca7","A line drawing of a solid with six equal square faces. Hidden edges are shown as dashed lines."],["02","What is the name of the solid in the picture?",["rectangle","cuboid","cube","triangular prism"],"cuboid","Six rectangular faces, with a length longer than the height, make a cuboid. A cube has six equal squares.","medium",60,["picture","cuboid","practice","medium"],["t0"],"esl-shape-cuboid.22955f8f2324.svg","22955f8f2324e69a26733c2c7d8d9a558c349d0427cfbf4ec24bc4ed716d2a4f","A line drawing of a box-shaped solid with six rectangular faces, longer than it is tall. Hidden edges are dashed."],["03","Look at the diagram. What do we call this 3D shape?",["cylinder","hemisphere","sphere","circle"],"sphere","A perfectly round solid like a ball is a sphere. A circle is the flat 2D shape.","easy",60,["picture","sphere","recheck","easy"],["t0"],"esl-shape-sphere.8ab58be916e8.svg","8ab58be916e86b0e751809c96ff1a4334f9ec83739ce8ab5a56ede67f801e1dd","A drawing of a perfectly round solid like a ball, with a dashed line around its middle."],["04","Which word names the shape in the picture?",["semicircle","sphere","cone","hemisphere"],"hemisphere","A dome with one flat circular face is half a sphere: a hemisphere.","medium",60,["picture","hemisphere","practice","medium"],["t0"],"esl-shape-hemisphere.05b7e0848ab7.svg","05b7e0848ab79049fa05c2a6c81f7208bcc31aff7d2dd492063d6884bff01f72","A drawing of a dome-shaped solid: a curved top resting on one flat circular face. The hidden back edge is dashed."],["05","Look carefully at the faces. Which solid is shown?",["cone","square-based pyramid","cylinder","triangle"],"cone","One circular base and a curved side rising to a point make a cone.","easy",60,["picture","cone","practice","easy"],["t0"],"esl-shape-cone.c4e7bfa498b1.svg","c4e7bfa498b18fe0ec8b36e1fee668df71dca7da7c538e07a8796635a9671380","A drawing of a solid with a circular base and a curved side that rises to one point. The hidden back of the base is dashed."],["06","Look at the picture. Which solid is this?",["cuboid","cylinder","cone","circle"],"cylinder","Two equal circular ends joined by a curved side make a cylinder.","easy",60,["picture","cylinder","recheck","easy"],["t0"],"esl-shape-cylinder.e69f931014c4.svg","e69f931014c453e0090ad3e90d30dc228c03775945b7fdba52d5aa4fbb9efc8e","A drawing of a solid with two equal circular ends joined by a curved side. The hidden back of the bottom circle is dashed."],["07","What is the name of the solid in the picture?",["triangle","triangular pyramid","triangular prism","cuboid"],"triangular prism","Two equal triangular ends joined by rectangles make a triangular prism. A pyramid ends in a point.","medium",60,["picture","triangular-prism","practice","medium"],["t0"],"esl-shape-triangular-prism.f55d3bc666f3.svg","f55d3bc666f3a0402c89d35bf44b97b859bed56aa1e7259306935c2bf20d6cea","A line drawing of a solid with two equal triangular ends joined by three rectangles. Hidden edges are dashed."],["08","Look at the diagram. What do we call this 3D shape?",["triangular prism","hexagon","cylinder","hexagonal prism"],"hexagonal prism","Two equal six-sided ends joined by rectangles make a hexagonal prism. A hexagon is only the flat end.","medium",60,["picture","hexagonal-prism","practice","medium"],["t0"],"esl-shape-hexagonal-prism.b2e1a8ab0a8b.svg","b2e1a8ab0a8bcf33f5e6516c748588f3cab1d5dc37d8a2ff7d331f8a5660d745","A line drawing of a solid with two equal six-sided ends joined by six rectangles. Hidden edges are dashed."],["09","Which word names the shape in the picture?",["square-based pyramid","triangular prism","triangular pyramid","cube"],"square-based pyramid","A square base with four triangles meeting at a point is a square-based pyramid.","medium",60,["picture","square-based-pyramid","recheck","medium"],["t0"],"esl-shape-square-based-pyramid.f2ee15c81108.svg","f2ee15c81108f7129b7c3d6557a762bbf6311e92ca75c7b60e8fe4e52e67b991","A line drawing of a solid with a square base and four triangular faces meeting at one point. Hidden edges are dashed."],["10","Look carefully at the faces. Which solid is shown?",["triangle","triangular pyramid","triangular prism","square-based pyramid"],"triangular pyramid","A triangular base with three triangles meeting at a point is a triangular pyramid.","hard",75,["picture","triangular-pyramid","practice","hard"],["t0"],"esl-shape-triangular-pyramid.ac9cd80c277e.svg","ac9cd80c277e752c0f954316fa02b7d2b80c7f10bf1b1e05659f6a33aaf0386b","A line drawing of a solid with a triangular base and three triangular faces meeting at one point. Hidden edges are dashed."],["11","Look at the four solids. What is the name of shape C?",["cylinder","hemisphere","cube","cone"],"cube","Shape C is a cube. Six equal square faces make a cube. A cuboid has rectangular faces that are not all the same.","medium",60,["picture","labelled shapes","practice","medium"],["t0"],"esl-shape-lineup-1.8dca1768dfe7.svg","8dca1768dfe71b21820d3ba24c28a662166be29e6138d4d3dd6a0c3ee3caa9ca","Four solid shapes in a row labelled A, B, C and D: a can shape, a shape with a point, a box shape, a dome."],["12","Look at the four solids. What is the name of shape B?",["sphere","square-based pyramid","cuboid","triangular prism"],"triangular prism","Shape B is a triangular prism. Two equal triangular ends joined by rectangles make a triangular prism. A pyramid ends in a point.","medium",60,["picture","labelled shapes","recheck","medium"],["t0"],"esl-shape-lineup-2.f484ed28044a.svg","f484ed28044a75b7f85450fd7cbdb2787a397298ffebb7d6b1e4f5c01411aa02","Four solid shapes in a row labelled A, B, C and D: a pointed shape on a square, a tent shape, a ball shape, a long box."],["13","Look at the four solids. What is the name of shape D?",["cone","triangular pyramid","cylinder","hexagonal prism"],"cone","Shape D is a cone. One circular base and a curved side rising to a point make a cone.","medium",60,["picture","labelled shapes","practice","medium"],["t0"],"esl-shape-lineup-3.ac62ac78094a.svg","ac62ac78094af1eccc07c1480dbd970caff2cdf0f322edc850531434afe296ac","Four solid shapes in a row labelled A, B, C and D: a pencil shape, a can shape, a pointed shape on a triangle, a shape with a point."],["14","Look at the object in the picture. Which solid is it shaped like?",["cuboid","triangular prism","cone","triangular pyramid"],"triangular prism","A camping tent: two triangular ends joined by rectangular sides.","medium",60,["picture","real-world objects","triangular-prism","practice","medium"],["t0"],"esl-shape-object-tent.1c42bcc4696a.svg","1c42bcc4696ae81609e909e189129f26b4c53f6dca5af6ea3dbc1905af2e9584","A drawing of a camping tent with a door, standing on the ground. It has two triangular ends and sloping rectangular sides."],["15","Look at the object in the picture. Which solid is it shaped like?",["cuboid","sphere","cylinder","cone"],"cylinder","A tin of food has two circular ends and a curved side: a cylinder.","medium",60,["picture","real-world objects","cylinder","recheck","medium"],["t0"],"esl-shape-object-tin.e82c6b9504ff.svg","e82c6b9504fff84ff84b6baa5d40abac63ae41553a537e645cf5e5da09a971e1","A drawing of a food tin with a coloured label band around its middle."],["16","Look at the object in the picture. Which solid is it shaped like?",["hemisphere","triangular pyramid","cylinder","cone"],"cone","An ice cream cone narrows from a circle to a single point: a cone.","medium",60,["picture","real-world objects","cone","practice","medium"],["t0"],"esl-shape-object-ice-cream.88aaa90b5e9f.svg","88aaa90b5e9f49ce7125c00a70c7413bb1e59e867f65f8ce8c7d667cc4356a55","A drawing of an ice cream: three scoops sitting on top of a crispy holder that narrows to a point at the bottom."],["17","Look at the object in the picture. Which solid is it shaped like?",["hemisphere","cylinder","cone","sphere"],"hemisphere","A dome-shaped building is half a sphere, with a flat circular floor: a hemisphere.","medium",60,["picture","real-world objects","hemisphere","practice","medium"],["t0"],"esl-shape-object-dome.a46f5cb8bb9a.svg","a46f5cb8bb9a88352fbd9270c562e2f52ee3bea14c63686bf621aec16fab612e","A drawing of a round dome-shaped building with a small door, standing on flat ground."],["18","Look at the cube. Which word names the part marked with the arrow?",["vertex","face","net","edge"],"face","A face is a flat surface of a solid. A cube has six faces.","easy",60,["picture","faces edges vertices","face","recheck","easy"],["t1"],"esl-shape-part-face.0ee97cbff1d8.svg","0ee97cbff1d8ecdf08cb40a08be70b5036549ffb719f969552bb663a13717e24","A cube drawing. One whole flat side of the cube is coloured amber and an arrow with a question mark points to it."],["19","Look at the cube. Which word names the part marked with the arrow?",["net","vertex","edge","face"],"edge","An edge is a line where two faces meet. A cube has twelve edges.","medium",60,["picture","faces edges vertices","edge","practice","medium"],["t1"],"esl-shape-part-edge.b6fe52b0876c.svg","b6fe52b0876c39b6270f83b2bd8174543af5413fb143475d3052d848735ae79b","A cube drawing. One straight line where two sides meet is thick and amber, and an arrow with a question mark points to it."],["20","Look at the cube. Which word names the part marked with the arrow?",["face","edge","net","vertex"],"vertex","A vertex is a corner point where edges meet. A cube has eight vertices.","medium",60,["picture","faces edges vertices","vertex","practice","medium"],["t1"],"esl-shape-part-vertex.f5ecd4b53a33.svg","f5ecd4b53a3373610a5a484c22b08861a5f8e0c4229cff7cd1d5e725ea156c2f","A cube drawing. One corner point is marked with an amber dot and an arrow with a question mark points to it."],["21","Look at the net. Which solid does it make when you fold it?",["cube","triangular prism","square-based pyramid","cuboid"],"cube","Six equal squares fold up into a cube.","medium",60,["picture","nets","cube","recheck","medium"],["t2"],"esl-shape-net-cube.392f9f9f0c6b.svg","392f9f9f0c6bb4edc5cec3d80a69f933da0a813c93196ea73cc19c2373da8678","A flat net made of six equal squares joined edge to edge in a cross pattern."],["22","Look at the net. Which solid does it make when you fold it?",["cube","square-based pyramid","triangular prism","triangular pyramid"],"square-based pyramid","One square with four triangles around it folds into a square-based pyramid.","hard",75,["picture","nets","square-based-pyramid","practice","hard"],["t2"],"esl-shape-net-square-based-pyramid.754a28b0c552.svg","754a28b0c552a41c6e95722e5ca8608820b0ab9a1b64e2fd87e225f6ed548a5d","A flat net made of one square in the middle with a triangle attached to each of its four sides."],["23","Look at the net. Which solid does it make when you fold it?",["triangular pyramid","hexagonal prism","triangular prism","cuboid"],"triangular prism","Three rectangles with a triangle at each end fold into a triangular prism.","hard",75,["picture","nets","triangular-prism","practice","hard"],["t2"],"esl-shape-net-triangular-prism.63ea8d9d0385.svg","63ea8d9d0385fa733246c9655920718472c968b1f486ab54254f5684c4a1e748","A flat net made of three rectangles in a row with one triangle attached at each end."],["24","Look at the net. Which solid does it make when you fold it?",["cone","sphere","cuboid","cylinder"],"cylinder","One rectangle with two equal circles folds into a cylinder: the rectangle rolls into the curved side.","hard",75,["picture","nets","cylinder","recheck","hard"],["t2"],"esl-shape-net-cylinder.f8da3974aa0b.svg","f8da3974aa0b069682dd9a06086dcbbfea13c90891fba974283f48952bc47db4","A flat net made of one rectangle with an equal circle touching its top edge and another touching its bottom edge."],["25","Shape A is a circle. What is the name of solid shape B?",["sphere","circle","cylinder","hemisphere"],"sphere","A circle is flat (2D). The solid, ball-shaped version is a sphere (3D).","easy",60,["picture","2D and 3D","sphere","practice","easy"],["t3"],"esl-shape-pair-circle-sphere.80f55ba2aa9d.svg","80f55ba2aa9de4faa121ec50bc13c49c072a6a9cc7b7877bae13d77c5aeffe6c","Two shapes labelled A and B. Shape A is a flat round shape. Shape B is a round solid like a ball."],["26","Shape A is a hexagon. What is the name of solid shape B?",["hexagonal pyramid","hexagonal prism","cylinder","hexagon"],"hexagonal prism","A hexagon is flat (2D). Two hexagons joined by rectangles make the solid hexagonal prism (3D).","medium",60,["picture","2D and 3D","hexagonal-prism","practice","medium"],["t3"],"esl-shape-pair-hexagon-prism.8518a8fa0924.svg","8518a8fa09248a7c1641742f41fada4d12d99d505f2a310d955f0a72827e56d7","Two shapes labelled A and B. Shape A is a flat six-sided shape. Shape B is a solid with six-sided ends joined by rectangles."],["27","Look at shapes A, B, C and D. Which one is a flat 2D shape?",["Shape A","Shape B","Shape C","Shape D"],"Shape C","Shape C is a triangle, which is flat (2D). A is a cone, B is a cube and D is a cylinder: all solid 3D shapes.","easy",60,["picture","2D and 3D","recheck","easy"],["t3"],"esl-shape-flat-or-solid.1c202ccce9d0.svg","1c202ccce9d081f239c8ab25f0abdab96921ba795df9e76f3d61e34d53f02bdf","Four shapes in a row labelled A to D. C is drawn flat with three straight sides. A, B and D are drawn as solids with depth and dashed hidden edges."]]}$pkg$;
  v_res jsonb; v_c jsonb; v_dig text;
  v_pkg jsonb; v_q jsonb; v_tx jsonb; v_reg public.academic_skill_registry_versions%rowtype;
  v_subj public.academic_subjects%rowtype; v_skill public.academic_skill_registry_nodes%rowtype;
  v_sub public.academic_skill_registry_nodes%rowtype; v_focus public.academic_skill_evidence_focuses%rowtype;
  v_strand public.academic_skill_registry_nodes%rowtype; v_p0 jsonb; v_id uuid; v_hash text; v_ext text;
  v_grades smallint[]; v_cv text; v_auth text; v_qn int := 0; v_tn int := 0; v_md5 text;
begin
  if md5(v_text) <> 'f4a38e66454fd77442cef796654a80ac' then raise exception 'shapes_visual_package_text_altered'; end if;
  v_c := v_text::jsonb;
  v_pkg := jsonb_build_object('schemaVersion',1,'packageId','esl-g7-shapes-visual-20261021','packageVersion','1.0.0',
    'contentVersion','esl-g7-shapes-visual-v1','registryVersion','bh-english-core-v1','subjectCode','english',
    'authority','Brains Heist Academic Governance',
    'releaseNotes','27 original picture-based MCQs for Grades 7-8 ESL (3D Shapes and Geometry Vocabulary): name the solid, labelled lineups, everyday objects, face/edge/vertex, nets, 2D vs 3D. 27 checksum-addressed SVGs under /question-assets/2026-10-21/. MCQ evidence only.',
    'questions',(select jsonb_agg(jsonb_build_object(
      'externalId','esl-g7-shapes-visual-20261021-'||(r->>0),'topic','3D Shapes and Geometry Vocabulary',
      'questionText',r->>1,'questionType','multiple_choice','options',r->2,'correctAnswer',r->>3,'explanation',r->>4,
      'difficulty',r->>5,'points',1,'timeLimit',(r->>6)::int,'language','en','eligibleGrades','[7,8]'::jsonb,
      'tags','["ESL", "grade-7", "grade-8", "geometry vocabulary", "2D and 3D shapes"]'::jsonb || (r->7),
      'hints','["Count the faces and check whether they are flat or curved."]'::jsonb,
      'taxonomies',(select jsonb_agg(v_c->'T'->(k#>>'{}') order by o) from jsonb_array_elements(r->8) with ordinality y(k,o)),
      'imageUrl','https://www.brainsheist.com/question-assets/2026-10-21/'||(r->>9),'imageSha256',r->>10,'imageAltText',r->>11) order by n)
      from jsonb_array_elements(v_c->'Q') with ordinality z(r,n)));
  select md5(string_agg((q->>'externalId')||'|'||(q->>'questionText')||'|'||
      (select string_agg(x,'~' order by i) from jsonb_array_elements_text(q->'options') with ordinality w(x,i))||'|'||
      (q->>'correctAnswer')||'|'||(q->>'explanation')||'|'||
      (select string_agg(x,',' order by i) from jsonb_array_elements_text(q->'tags') with ordinality w(x,i))||'|'||
      (q->>'imageUrl')||'|'||(q->>'imageAltText')||'|'||
      (select string_agg((t->>'evidenceFocusCode')||'/'||(t->>'assessmentProcessCode')||'/'||(t->>'cognitiveProcess'),';' order by i) from jsonb_array_elements(q->'taxonomies') with ordinality w(t,i)),
      E'\n' order by n)) into v_dig from jsonb_array_elements(v_pkg->'questions') with ordinality u(q,n);
  if v_dig <> '7c750003fb51bd583588c343d9e35c61' then raise exception 'shapes_visual_expansion_mismatch:%', v_dig; end if;
  v_res := public.rpc_import_registry_verified_mcq_package(
    jsonb_set(v_pkg,'{questions}',(select jsonb_agg(q - 'imageUrl' - 'imageAltText' - 'imageSha256' order by o)
      from jsonb_array_elements(v_pkg->'questions') with ordinality x(q,o))), true);
  if not coalesce((v_res->>'success')::boolean,false) or (v_res->>'alreadyImported')::boolean then
    raise exception 'shapes_visual_dry_run_failed:%', v_res;
  end if;
  if exists(select 1 from public.registry_verified_question_import_releases where package_id=v_pkg->>'packageId') then
    raise exception 'shapes_visual_already_released'; end if;
  v_cv := v_pkg->>'contentVersion'; v_auth := v_pkg->>'authority';
  select * into strict v_reg from public.academic_skill_registry_versions where code=v_pkg->>'registryVersion' and status='published';
  select * into strict v_subj from public.academic_subjects where code=v_pkg->>'subjectCode' and is_active;
  for v_q in select value from jsonb_array_elements(v_pkg->'questions') loop
    v_ext := v_q->>'externalId';
    if (v_q->>'imageUrl') !~ '^https://www\.brainsheist\.com/question-assets/2026-10-21/[a-z0-9-]+\.[0-9a-f]{12}\.svg$'
       or position(substr(v_q->>'imageSha256',1,12) in v_q->>'imageUrl')=0
       or length(trim(v_q->>'imageAltText')) not between 20 and 240 then
      raise exception 'shapes_visual_invalid_image:%', v_ext; end if;
    select array_agg(distinct g::smallint order by g::smallint) into v_grades from jsonb_array_elements_text(v_q->'eligibleGrades') g;
    v_p0 := v_q->'taxonomies'->0;
    select * into strict v_skill from public.academic_skill_registry_nodes where registry_version_id=v_reg.id and code=v_p0->>'primarySkillCode' and node_type='skill' and status='active';
    select * into strict v_sub from public.academic_skill_registry_nodes where registry_version_id=v_reg.id and code=v_p0->>'atomicSubskillCode' and parent_id=v_skill.id and node_type='subskill' and status='active';
    select * into strict v_strand from public.academic_skill_registry_nodes where id=v_skill.parent_id and registry_version_id=v_reg.id and node_type='strand' and status='active';
    v_md5 := md5('registry-verified-question:'||v_ext);
    v_id := (substr(v_md5,1,8)||'-'||substr(v_md5,9,4)||'-'||substr(v_md5,13,4)||'-'||substr(v_md5,17,4)||'-'||substr(v_md5,21,12))::uuid;
    v_hash := private.question_content_hash(v_id, v_q->>'questionText', v_q->'options', v_q->>'correctAnswer', v_q->>'explanation', v_q->>'imageUrl', 'multiple_choice');
    insert into public.questions(
      id,teacher_id,subject,subject_id,topic,topic_name,difficulty,question_text,question_type,options,correct_answer,explanation,hints,
      time_limit,points,tags,grade_level,grade,lang,is_public,is_active,academic_subject_id,curriculum_strand,curriculum_skill,curriculum_subskill,
      curriculum_objective,eligible_grade_levels,curriculum_review_status,content_origin,pool_scope,owner_school_id,verification_status,
      analytics_eligible,verified_at,verified_by,verified_by_authority,verified_content_hash,content_version,content_revision,verified_external_id,
      image_url,image_alt_text
    ) values (
      v_id,null,v_subj.name,v_subj.code,v_q->>'topic',v_q->>'topic',v_q->>'difficulty',v_q->>'questionText','multiple_choice',v_q->'options',
      v_q->>'correctAnswer',v_q->>'explanation',array(select jsonb_array_elements_text(v_q->'hints')),(v_q->>'timeLimit')::int,1,
      array(select jsonb_array_elements_text(v_q->'tags')),'Grade '||v_grades[1]::text,v_grades[1],'en',true,true,v_subj.id,
      v_strand.name,v_skill.name,v_sub.name,v_p0->>'evidenceStatement',v_grades,'approved','brain_heist','global',null,'verified',
      true,now(),null,v_auth,v_hash,v_cv,1,v_ext,v_q->>'imageUrl',v_q->>'imageAltText');
    v_qn := v_qn + 1;
    for v_tx in select value from jsonb_array_elements(v_q->'taxonomies') loop
      select * into strict v_skill from public.academic_skill_registry_nodes where registry_version_id=v_reg.id and code=v_tx->>'primarySkillCode' and node_type='skill' and status='active';
      select * into strict v_sub from public.academic_skill_registry_nodes where registry_version_id=v_reg.id and code=v_tx->>'atomicSubskillCode' and parent_id=v_skill.id and node_type='subskill' and status='active';
      select * into strict v_focus from public.academic_skill_evidence_focuses where registry_version_id=v_reg.id and atomic_subskill_node_id=v_sub.id and code=v_tx->>'evidenceFocusCode' and status='active';
      insert into public.verified_question_registry_taxonomy(question_id,question_content_hash,registry_version_id,primary_skill_node_id,
        atomic_subskill_node_id,evidence_focus_id,taxonomy_version,assessment_process_code,cognitive_process,evidence_statement,confidence_score,
        review_status,human_review_required,source_method,reviewed_by_authority,taxonomy_hash)
      values (v_id,v_hash,v_reg.id,v_skill.id,v_sub.id,v_focus.id,v_cv||':'||v_ext,v_tx->>'assessmentProcessCode',v_tx->>'cognitiveProcess',
        v_tx->>'evidenceStatement',1,'approved',false,'verified_package_import',v_auth,'pending');
      v_tn := v_tn + 1;
    end loop;
  end loop;
  insert into public.registry_verified_question_import_releases(package_id,package_version,schema_version,content_version,registry_version_id,
    academic_subject_id,package_hash,question_count,taxonomy_count,assessment_profile_count,release_notes,imported_by_authority)
  values (v_pkg->>'packageId',v_pkg->>'packageVersion',1,v_cv,v_reg.id,v_subj.id,encode(extensions.digest(v_pkg::text,'sha256'),'hex'),
    v_qn,v_tn,0,v_pkg->>'releaseNotes',v_auth);
  set constraints all immediate;
  raise exception 'REHEARSAL_OK questions=% taxonomy=%', v_qn, v_tn;
end $do$;
